var IDENTITY_KEY_PREFIX = "nurish-smart-student-identity:";
function readStoredIdentity(token) {
	try {
		const raw = localStorage.getItem(`${IDENTITY_KEY_PREFIX}${token}`);
		if (!raw) return null;
		const parsed = JSON.parse(raw);
		if (typeof parsed.fullName !== "string" || typeof parsed.participantId !== "string" || typeof parsed.className !== "string" || typeof parsed.schoolName !== "string" || parsed.educationLevel !== EducationLevel.sdMi && parsed.educationLevel !== EducationLevel.smpMts) return null;
		return {
			fullName: parsed.fullName,
			participantId: parsed.participantId,
			className: parsed.className,
			schoolName: parsed.schoolName,
			educationLevel: parsed.educationLevel
		};
	} catch {
		return null;
	}
}
function storeIdentity(token, identity) {
	try {
		localStorage.setItem(`${IDENTITY_KEY_PREFIX}${token}`, JSON.stringify(identity));
	} catch {}
}
